#!/bin/bash
# Run manually to publish. Preparing this script does not publish anything.
set -euo pipefail
source_dir="$(cd "$(dirname "$0")/.." && pwd)"
task_dir="$(cd "$source_dir/../.." && pwd)"
repo_dir="$task_dir/work/publish-repository"
export GH_CONFIG_DIR="$task_dir/work/github-cli"
gh_bin="$task_dir/work/tools/gh"
if [ ! -x "$gh_bin" ]; then gh_bin="$(command -v gh)"; fi
"$gh_bin" auth status --hostname github.com
[ "$(git -C "$repo_dir" remote get-url origin)" = 'https://github.com/SkyyRacer/starlink-atlas.git' ] || { echo 'Dépôt cible inattendu : arrêt.'; exit 1; }
[ "$(git -C "$repo_dir" branch --show-current)" = main ] || { echo 'Le dépôt de publication doit être sur main.'; exit 1; }
[ -z "$(git -C "$repo_dir" status --porcelain)" ] || { echo 'Le dépôt de publication contient des modifications. Les vérifier avant de relancer.'; exit 1; }
"$gh_bin" auth setup-git --hostname github.com
git -C "$repo_dir" pull --ff-only origin main
# Keep the existing orbital history and Git metadata. Copy only project sources.
rsync -a --exclude=.git --exclude=target --exclude=data --exclude=data-runtime --exclude=public --exclude=.env --exclude=.DS_Store --exclude=__pycache__ --exclude='*.pyc' --exclude='*.zip' --exclude='*.zip.sha256' "$source_dir/" "$repo_dir/"
mkdir -p "$repo_dir/data-seed"
for file in gp-proba-2.json proba-2-catalog.json proba-2-attempt.txt proba-2-fetched.txt gp-proba-3.json proba-3-catalog.json proba-3-attempt.txt proba-3-fetched.txt gp-mev-1.json mev-1-catalog.json mev-1-attempt.txt mev-1-fetched.txt gp-mev-2.json mev-2-catalog.json mev-2-attempt.txt mev-2-fetched.txt gp-lares-2.json lares-2-catalog.json lares-2-attempt.txt lares-2-fetched.txt gp-tiangong.json tiangong-catalog.json tiangong-attempt.txt tiangong-fetched.txt tiangong-missions.json tiangong-missions-attempt.txt tiangong-missions-full.txt gp-analyst.json analyst-attempt.txt analyst-fetched.txt satcat-all.csv iss-missions.json iss-evas.json iss-missions-attempt.txt iss-missions-full.txt iss-evas-attempt.txt iss-evas-full.txt gp-aleph-1.json aleph-1-catalog.json aleph-1-attempt.txt aleph-1-fetched.txt gp-alos-2.json alos-2-catalog.json alos-2-attempt.txt alos-2-fetched.txt gp-alos-4.json alos-4-catalog.json alos-4-attempt.txt alos-4-fetched.txt gp-amazon-leo.json amazon-leo-catalog.json amazon-leo-attempt.txt amazon-leo-fetched.txt gp-arabsat.json arabsat-catalog.json arabsat-attempt.txt arabsat-fetched.txt gp-ast-spacemobile.json ast-spacemobile-catalog.json ast-spacemobile-attempt.txt ast-spacemobile-fetched.txt gp-astrosat.json astrosat-catalog.json astrosat-attempt.txt astrosat-fetched.txt gp-beidou.json beidou-catalog.json beidou-attempt.txt beidou-fetched.txt gp-biomass.json biomass-catalog.json biomass-attempt.txt biomass-fetched.txt gp-blacksky-gen2.json blacksky-gen2-catalog.json blacksky-gen2-attempt.txt blacksky-gen2-fetched.txt gp-blacksky-gen3.json blacksky-gen3-catalog.json blacksky-gen3-attempt.txt blacksky-gen3-fetched.txt gp-capella.json capella-catalog.json capella-attempt.txt capella-fetched.txt gp-cartosat-3.json cartosat-3-catalog.json cartosat-3-attempt.txt cartosat-3-fetched.txt gp-chandra.json chandra-catalog.json chandra-attempt.txt chandra-fetched.txt gp-cheops.json cheops-catalog.json cheops-attempt.txt cheops-fetched.txt gp-cosmo-skymed.json cosmo-skymed-catalog.json cosmo-skymed-attempt.txt cosmo-skymed-fetched.txt gp-cryosat-2.json cryosat-2-catalog.json cryosat-2-attempt.txt cryosat-2-fetched.txt gp-debris.json debris-catalog.json debris-attempt.txt debris-fetched.txt gp-earthcare.json earthcare-catalog.json earthcare-attempt.txt earthcare-fetched.txt gp-edrs.json edrs-catalog.json edrs-attempt.txt edrs-fetched.txt gp-eros-c3.json eros-c3-catalog.json eros-c3-attempt.txt eros-c3-fetched.txt gp-fengyun-3.json fengyun-3-catalog.json fengyun-3-attempt.txt fengyun-3-fetched.txt gp-fengyun-4.json fengyun-4-catalog.json fengyun-4-attempt.txt fengyun-4-fetched.txt gp-fermi.json fermi-catalog.json fermi-attempt.txt fermi-fetched.txt gp-galileo.json galileo-catalog.json galileo-attempt.txt galileo-fetched.txt gp-gaofen-3.json gaofen-3-catalog.json gaofen-3-attempt.txt gaofen-3-fetched.txt gp-geesatcom.json geesatcom-catalog.json geesatcom-attempt.txt geesatcom-fetched.txt gp-ghgsat.json ghgsat-catalog.json ghgsat-attempt.txt ghgsat-fetched.txt gp-globalstar.json globalstar-catalog.json globalstar-attempt.txt globalstar-fetched.txt gp-glonass.json glonass-catalog.json glonass-attempt.txt glonass-fetched.txt gp-goes.json goes-catalog.json goes-attempt.txt goes-fetched.txt gp-goes-18.json goes-18-catalog.json goes-18-attempt.txt goes-18-fetched.txt gp-goes-19.json goes-19-catalog.json goes-19-attempt.txt goes-19-fetched.txt gp-gps.json gps-catalog.json gps-attempt.txt gps-fetched.txt gp-grace-fo.json grace-fo-catalog.json grace-fo-attempt.txt grace-fo-fetched.txt gp-himawari.json himawari-catalog.json himawari-attempt.txt himawari-fetched.txt gp-hubble.json hubble-catalog.json hubble-attempt.txt hubble-fetched.txt gp-iceye.json iceye-catalog.json iceye-attempt.txt iceye-fetched.txt gp-inmarsat.json inmarsat-catalog.json inmarsat-attempt.txt inmarsat-fetched.txt gp-insat-3ds.json insat-3ds-catalog.json insat-3ds-attempt.txt insat-3ds-fetched.txt gp-iridium.json iridium-catalog.json iridium-attempt.txt iridium-fetc