nstellation.json radarsat-constellation-catalog.json radarsat-constellation-attempt.txt radarsat-constellation-fetched.txt gp-radarsat-2.json radarsat-2-catalog.json radarsat-2-attempt.txt radarsat-2-fetched.txt gp-sateliot.json sateliot-catalog.json sateliot-attempt.txt sateliot-fetched.txt gp-sentinel.json sentinel-catalog.json sentinel-attempt.txt sentinel-fetched.txt gp-sentinel-5p.json sentinel-5p-catalog.json sentinel-5p-attempt.txt sentinel-5p-fetched.txt gp-sentinel-6.json sentinel-6-catalog.json sentinel-6-attempt.txt sentinel-6-fetched.txt gp-skysat.json skysat-catalog.json skysat-attempt.txt skysat-fetched.txt gp-smap.json smap-catalog.json smap-attempt.txt smap-fetched.txt gp-spacesail.json spacesail-catalog.json spacesail-attempt.txt spacesail-fetched.txt gp-spire-lemur.json spire-lemur-catalog.json spire-lemur-attempt.txt spire-lemur-fetched.txt gp-spot.json spot-catalog.json spot-attempt.txt spot-fetched.txt gp-starlink.json starlink-catalog.json starlink-attempt.txt starlink-fetched.txt gp-swarm.json swarm-catalog.json swarm-attempt.txt swarm-fetched.txt gp-swot.json swot-catalog.json swot-attempt.txt swot-fetched.txt gp-tdrss.json tdrss-catalog.json tdrss-attempt.txt tdrss-fetched.txt gp-tess.json tess-catalog.json tess-attempt.txt tess-fetched.txt gp-thuraya.json thuraya-catalog.json thuraya-attempt.txt thuraya-fetched.txt gp-umbra.json umbra-catalog.json umbra-attempt.txt umbra-fetched.txt gp-viasat.json viasat-catalog.json viasat-attempt.txt viasat-fetched.txt gp-worldview-legion.json worldview-legion-catalog.json worldview-legion-attempt.txt worldview-legion-fetched.txt gp-worldview-3.json worldview-3-catalog.json worldview-3-attempt.txt worldview-3-fetched.txt gp-xmm-newton.json xmm-newton-catalog.json xmm-newton-attempt.txt xmm-newton-fetched.txt gp-xposat.json xposat-catalog.json xposat-attempt.txt xposat-fetched.txt gp-xrism.json xrism-catalog.json xrism-attempt.txt xrism-fetched.txt; do
  if [ -f "$source_dir/data/$file" ]; then cp "$source_dir/data/$file" "$repo_dir/data-seed/$file"; fi
done
# Keep the newest validated backup for each experimental family, plus the initial shared set.
python3 - "$source_dir/data" "$repo_dir/data-seed" <<'PYSEED'
import pathlib,shutil,sys
source,target=map(pathlib.Path,sys.argv[1:])
for key in ['experimental','proba-2','proba-3','mev-1','mev-2','lares-2','tess','xposat']:
    files=list(source.glob('gp-backup-'+key+'-*.json'))
    if files:
        newest=max(files,key=lambda p:p.stat().st_mtime)
        shutil.copy2(newest,target/newest.name)
PYSEED
git -C "$repo_dir" add -A
if ! git -C "$repo_dir" diff --cached --quiet; then
  git -C "$repo_dir" commit -m 'Pages Atlas ISS et Starlink, fiches astronautes, EVA et interface'
fi
"$gh_bin" api --method PUT repos/SkyyRacer/starlink-atlas/pages -f build_type=workflow >/dev/null
git -C "$repo_dir" push origin main
echo 'Envoi terminé. GitHub Actions compile et publie ensuite le site.'
"$gh_bin" run list --repo SkyyRacer/starlink-atlas --workflow publish.yml --limit 3
echo 'Suivi : https://github.com/SkyyRacer/starlink-atlas/actions'
echo 'Site : https://skyyracer.github.io/starlink-atlas/'
